# Build regex: longest aliases first to avoid partial matches
_ALIAS_PATTERN = '|'.join(
    re.escape(k)
    for k in sorted(BOOK_ALIASES.keys(), key=len, reverse=True)
)

# Matches "John 8:7", "1 Cor 13:4-7", "Psalm 23", "Rev 21:4", etc.
VERSE_RE = re.compile(
    r'\b(' + _ALIAS_PATTERN + r')\s+(\d{1,3})'
    r'(?::(\d{1,3})(?:\s*[-–]\s*(\d{1,3}))?)?'
    r'\b',
    re.IGNORECASE,
)

